class Solution:
    def binaryReflectionSort(self, nums):
        def reflect(x):
            r = 0
            while x:
                r = r * 2 + (x & 1)
                x >>= 1
            return r
        return [v for _, v in sorted((reflect(x), x) for x in nums)]

