class Solution {
public:
    vector<int> binaryReflectionSort(vector<int>& nums) {
        auto reflect = [](long long x) {
            long long r = 0;
            while (x) { r = r * 2 + (x & 1); x >>= 1; }
            return r;
        };
        vector<pair<long long,int>> v;
        for (int x : nums) v.push_back({reflect(x), x});
        sort(v.begin(), v.end());
        vector<int> res;
        for (auto& p : v) res.push_back(p.second);
        return res;
    }
};

