class Solution {
    public int[] binaryReflectionSort(int[] nums) {
        int[][] arr = new int[nums.length][2];
        for (int i = 0; i < nums.length; i++) {
            long x = nums[i], r = 0;
            while (x > 0) { r = r * 2 + (x & 1); x >>= 1; }
            arr[i][0] = (int) r;
            arr[i][1] = nums[i];
        }
        java.util.Arrays.sort(arr, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        int[] res = new int[nums.length];
        for (int i = 0; i < nums.length; i++) res[i] = arr[i][1];
        return res;
    }
}

