class Solution {
public:
    vector<int> binaryReflectionSort(vector<int>& nums) {
        auto reflect = [](int x) {
            int r = 0;
            while (x) { r = r * 2 + (x & 1); x >>= 1; }
            return r;
        };
        int n = nums.size();
        vector<int> ref(n);
        for (int i = 0; i < n; i++) ref[i] = reflect(nums[i]);
        for (int i = 0; i < n; i++) {
            int m = i;
            for (int j = i + 1; j < n; j++)
                if (make_pair(ref[j], nums[j]) < make_pair(ref[m], nums[m])) m = j;
            swap(nums[i], nums[m]);
            swap(ref[i], ref[m]);
        }
        return nums;
    }
};

