class Solution {
    public int[] binaryReflectionSort(int[] nums) {
        int n = nums.length;
        long[] ref = new long[n];
        for (int i = 0; i < n; i++) {
            long x = nums[i], r = 0;
            while (x > 0) { r = r * 2 + (x & 1); x >>= 1; }
            ref[i] = r;
        }
        for (int i = 0; i < n; i++) {
            int m = i;
            for (int j = i + 1; j < n; j++) {
                if (ref[j] < ref[m] || (ref[j] == ref[m] && nums[j] < nums[m])) m = j;
            }
            long tr = ref[i]; ref[i] = ref[m]; ref[m] = tr;
            int tv = nums[i]; nums[i] = nums[m]; nums[m] = tv;
        }
        return nums;
    }
}

