var binaryReflectionSort = function(nums) {
    const reflect = (x) => {
        let r = 0;
        while (x > 0) { r = r * 2 + (x & 1); x >>>= 1; }
        return r;
    };
    const ref = nums.map(reflect);
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        let m = i;
        for (let j = i + 1; j < n; j++) {
            if (ref[j] < ref[m] || (ref[j] === ref[m] && nums[j] < nums[m])) m = j;
        }
        [nums[i], nums[m]] = [nums[m], nums[i]];
        [ref[i], ref[m]] = [ref[m], ref[i]];
    }
    return nums;
};
